195→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
196→    );
197→  };
198→
199→  const requireAuth = useCallback(() => {
200→    if (!user) { setAuthOpen(true); return true; }
201→    return false;
202→  }, [user]);
203→
204→  return (
