206→      <JobSidebar
207→        pastJobs={pastJobs}
208→        selectedJobId={selectedJobId}
209→        loadingPastJobs={loadingPastJobs}
210→        onSelectJob={loadJobData}
211→        onNewJob={handleNewJob}
212→        onRenameJob={handleRenameJob}
213→        onDeleteJob={handleDeleteJob}
214→        onAuthRequired={() => setAuthOpen(true)}
215→        isAuthenticated={!!user}
216→      />
217→
218→      <SidebarInset className="h-svh overflow-y-auto">
219→        <AppHeader />
220→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
221→          <SidebarTrigger />
222→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
223→        </div>
224→        <JobDetailView
225→          selectedJobId={selectedJobId}
226→          selectedJob={selectedJob}
227→          results={results}
228→          setResults={setResults}
229→          existingResumes={existingResumes}
230→          setExistingResumes={setExistingResumes}
231→          onJobCreated={handleJobCreated}
232→          onAuthRequired={() => setAuthOpen(true)}
233→          isAuthenticated={!!user}
234→          onJobUpdated={handleJobUpdated}
235→        />
236→      </SidebarInset>
237→
238→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
239→    </SidebarProvider>
