        <ol className="text-sm list-decimal list-inside space-y-1 text-muted-foreground mt-2 pl-2">
          {questions.map((q: string, i: number) => <li key={i}>{q}</li>)}
        </ol>
      )}
    </div>
  );
};

export default InterviewQuestionsPanel;

