                            <div key={i} className="flex items-center gap-2 text-xs px-2.5 py-1.5 rounded-md bg-destructive/5 border border-destructive/15 text-foreground">
                              <XCircle className="h-3 w-3 text-destructive shrink-0" />
                              {g}
                            </div>
                          ))}
                        </div>
                      </div>
                    </div>
                  )}

                  {/* Interview Questions */}
                  {r.interview_questions && Array.isArray(r.interview_questions) && r.interview_questions.length > 0 && (
                    <div>
