import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { XCircle } from "lucide-react";
import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
import { format } from "date-fns";

interface StageTrackerProps {
  currentStage: HiringStage;
  updatedAt?: string | null;
  onStageChange: (stage: HiringStage) => void;
  disabled?: boolean;
}

const STAGE_LABELS: Record<string, string> = {
  applied: "Applied",
  screened: "Screened",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
};

const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
  const isRejected = currentStage === "rejected";

  return (
    <div className="flex items-center gap-2">
      <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>

      <div className="flex items-center gap-0 flex-1 min-w-0">
        {STAGE_ORDER.map((stage, i) => {
          const isCompleted = !isRejected && i < currentIndex;
          const isCurrent = !isRejected && i === currentIndex;
          const isUpcoming = isRejected || i > currentIndex;

          return (
            <div key={stage} className="flex items-center">
              {/* Dot */}
              <TooltipProvider delayDuration={200}>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      disabled={disabled}
                      onClick={(e) => {
                        e.stopPropagation();
                        onStageChange(stage);
                      }}
                      className={cn(
                        "w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold transition-all shrink-0",
                        "focus:outline-none focus:ring-2 focus:ring-primary/30",
                        isCompleted && "bg-emerald-500 text-white",
                        isCurrent && "bg-primary text-white ring-2 ring-primary/30",
                        isUpcoming && "bg-muted border border-border text-muted-foreground",
                        !disabled && "cursor-pointer hover:scale-110",
                        disabled && "cursor-default"
                      )}
                    >
                      {isCompleted ? "✓" : i + 1}
                    </button>
                  </TooltipTrigger>
                  <TooltipContent className="text-xs">
                    {isCompleted ? `${STAGE_LABELS[stage]} (done)` : isCurrent ? `${STAGE_LABELS[stage]} (current)` : `Move to ${STAGE_LABELS[stage]}`}
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>

              {/* Connector line */}
              {i < STAGE_ORDER.length - 1 && (
                <div
                  className={cn(
                    "h-0.5 w-6 sm:w-8 transition-all",
                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
                  )}
                />
              )}
            </div>
          );
        })}
      </div>

      {/* Labels row - shown below on small screens, inline on larger */}
      <div className="hidden sm:flex items-center gap-1">
        {/* Reject button */}
        <TooltipProvider delayDuration={200}>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                disabled={disabled}
                className={cn(
                  "h-6 w-6",
                  isRejected ? "text-destructive" : "text-muted-foreground/50 hover:text-destructive"
                )}
                onClick={(e) => {
                  e.stopPropagation();
                  onStageChange("rejected");
                }}
              >
                <XCircle className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent className="text-xs">Reject candidate</TooltipContent>
          </Tooltip>
        </TooltipProvider>
      </div>

      {/* Rejected badge */}
      {isRejected && (
        <Badge variant="destructive" className="text-[10px] shrink-0">Rejected</Badge>
      )}

      {/* Updated timestamp */}
      {updatedAt && (
        <span className="text-[10px] text-muted-foreground shrink-0 hidden sm:inline">
          Updated {format(new Date(updatedAt), "MMM d")}
        </span>
      )}
    </div>
  );
};

export default StageTracker;

