import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import {
  ChevronDown, ChevronUp, Download, Phone, Mail, MapPin,
  FileText, Archive
} from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";

// Sub-components
import CandidateSummary from "@/components/candidate/CandidateSummary";
import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
import ExperiencePanel from "@/components/candidate/ExperiencePanel";
import EducationPanel from "@/components/candidate/EducationPanel";
import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
import AINudgePanel from "@/components/candidate/AINudgePanel";
import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
import StageTracker from "@/components/candidate/StageTracker";
import type { HiringStage } from "@/hooks/useStageTracker";

interface CandidateRowProps {
  result: Result;
  index: number;
  isExpanded: boolean;
  isSelected: boolean;
  jobTitle?: string | null;
  onToggleRow: (id: string) => void;
  onToggleSelect: (resumeId: string) => void;
  onDownload: (filePath: string, filename: string) => void;
  onDelete: (resumeId: string, filePath: string | null) => void;
  onDismiss: (resumeId: string) => void;
  formatCandidateName: (filename: string) => string;
  currentStage?: HiringStage | null;
  stageUpdatedAt?: string | null;
  onStageChange?: (resumeId: string, stage: HiringStage) => void;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "bg-score-skills";
  if (score >= 40) return "bg-warning";
  return "bg-destructive";
};

const getScoreTextColor = (score: number) => {
  if (score >= 70) return "text-score-skills";
  if (score >= 40) return "text-warning";
  return "text-destructive";
};

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const getRankDisplay = (index: number) => {
  if (index < 3) {
    const colors = [
      "bg-score-overall text-white",
      "bg-muted-foreground/60 text-white",
      "bg-warning text-white",
    ];
    return (
      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
        {index + 1}
      </span>
    );
  }
  return (
    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
      {index + 1}
    </span>
  );
};

const CandidateRow = ({
  result: r,
  index,
  isExpanded,
  isSelected,
  jobTitle,
  onToggleRow,
  onToggleSelect,
  onDownload,
  onDelete,
  onDismiss,
  formatCandidateName,
  currentStage,
  stageUpdatedAt,
  onStageChange,
}: CandidateRowProps) => {
  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;

  return (
    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
      <>
        {/* Collapsed Row */}
        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
          <TableCell onClick={(e) => e.stopPropagation()}>
            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
          </TableCell>
          <TableCell className="text-center">
            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
          </TableCell>
          <TableCell className="font-medium">
            <div className="flex flex-col">
              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
              {r.candidate_location && (
                <span className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
                  <MapPin className="h-3 w-3" /> {r.candidate_location}
                </span>
              )}
            </div>
          </TableCell>
          <TableCell>
            {r.pending ? (
              <Badge variant="outline" className="text-xs">Pending</Badge>
            ) : (
              <div className="flex items-center gap-2">
                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
                  <div
                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                  />
                </div>
                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
                  {r.overall_score?.toFixed(0)}%
                </span>
              </div>
            )}
          </TableCell>
          <TableCell>
            <div className="flex flex-wrap items-center gap-1">
              {!r.pending && strength && (
                <Badge variant={strength.variant} className="text-[10px]">
                  {strength.label}
                </Badge>
              )}
              {!r.pending && r.scoring_version === "heuristic" && (
                <TooltipProvider delayDuration={300}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
                        Quick
                      </span>
                    </TooltipTrigger>
                    <TooltipContent className="max-w-xs text-xs">
                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              )}
            </div>
          </TableCell>
          <TableCell>
            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
              <TooltipProvider delayDuration={300}>
                {/* Phone */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.candidate_phone ? (
                      <a
                        href={`tel:${r.candidate_phone}`}
                        onClick={(e) => {
                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
                            e.preventDefault();
                            navigator.clipboard.writeText(r.candidate_phone!);
                            toast.success("Phone number copied!");
                          }
                        }}
                      >
                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
                          <Phone className="h-3.5 w-3.5" />
                        </Button>
                      </a>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Phone className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_phone ? (/Mobi|Android/i.test(navigator.userAgent) ? r.candidate_phone : "Copy phone") : "No phone"}</TooltipContent>
                </Tooltip>

                {/* Email */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.candidate_email ? (
                      <a href={`mailto:${r.candidate_email}?subject=${encodeURIComponent(`Regarding Your Application – ${jobTitle || "Open Position"}`)}`}>
                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
                          <Mail className="h-3.5 w-3.5" />
                        </Button>
                      </a>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Mail className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_email || "No email"}</TooltipContent>
                </Tooltip>

                {/* Download */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.file_path ? (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
                        <FileText className="h-3.5 w-3.5" />
                      </Button>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <FileText className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
                </Tooltip>

                {/* Archive */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost" size="icon"
                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
                      onClick={() => onDismiss(r.resume_id)}
                    >
                      <Archive className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Archive candidate</TooltipContent>
                </Tooltip>
              </TooltipProvider>

              {!r.pending && (
                <CollapsibleTrigger asChild>
                  <Button variant="ghost" size="icon" className="h-7 w-7">
                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
                  </Button>
                </CollapsibleTrigger>
              )}
            </div>
          </TableCell>
        </TableRow>

        {/* Expanded Detail — New Layout */}
        {!r.pending && (
          <CollapsibleContent asChild>
            <TableRow className="bg-muted/30 hover:bg-muted/30">
              <TableCell colSpan={6} className="p-5">
                <div className="space-y-4">
                  {/* 1. AI Summary */}
                  <CandidateSummary result={r} />

                  {/* 2. Stage Tracker */}
                  {onStageChange && (
                    <StageTracker
                      currentStage={currentStage || "applied"}
                      updatedAt={stageUpdatedAt}
                      onStageChange={(stage) => onStageChange(r.resume_id, stage)}
                    />
                  )}

                  {/* 3. Skills Detail | Experience | Education — 3 columns */}
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <SkillsDetailPanel result={r} />
                    <ExperiencePanel parsedJson={r.parsed_json} />
                    <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} />
                  </div>

                  {/* 4. JD Aligned — full width */}
                  <JDAlignedPanel result={r} />

                  {/* 5. Strengths & Gaps — full width */}
                  <StrengthsGapsPanel result={r} />

                  {/* 6. AI Nudge */}
                  <AINudgePanel result={r} />

                  {/* 7. Interview Questions — collapsible */}
                  <InterviewQuestionsPanel result={r} />
                </div>
              </TableCell>
            </TableRow>
          </CollapsibleContent>
        )}
      </>
    </Collapsible>
  );
};

export default CandidateRow;

