import { Badge } from "@/components/ui/badge";
import { Briefcase } from "lucide-react";

interface Role {
  title?: string;
  company?: string;
  start?: string;
  end?: string;
  description?: string;
}

interface ExperiencePanelProps {
  parsedJson: any;
}

const ExperiencePanel = ({ parsedJson }: ExperiencePanelProps) => {
  const roles: Role[] = parsedJson?.roles_with_dates || parsedJson?.experience || [];
  const totalYears = roles.length > 0
    ? roles.reduce((sum, r) => {
        if (!r.start) return sum;
        const startYear = parseInt(r.start);
        const endYear = r.end && r.end.toLowerCase() !== "current" && r.end.toLowerCase() !== "present"
          ? parseInt(r.end)
          : new Date().getFullYear();
        return sum + Math.max(0, (endYear || 0) - (startYear || 0));
      }, 0)
    : null;

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
        {totalYears !== null && totalYears > 0 && (
          <Badge variant="outline" className="ml-auto text-[10px]">{totalYears} yrs</Badge>
        )}
      </div>

      {roles.length > 0 ? (
        <div className="space-y-3">
          {roles.slice(0, 4).map((role, i) => {
            const duration = role.start && role.end
              ? `${role.start} – ${role.end}`
              : role.start || "";
            const isCurrentRole = role.end?.toLowerCase() === "current" || role.end?.toLowerCase() === "present";

            return (
              <div key={i} className="flex gap-2">
                <div className="flex flex-col items-center mt-1">
                  <div className={`w-2 h-2 rounded-full shrink-0 ${i === 0 ? "bg-purple-500" : "bg-muted-foreground/40"}`} />
                  {i < Math.min(roles.length, 4) - 1 && <div className="w-px flex-1 bg-border mt-1" />}
                </div>
                <div className="space-y-0.5 min-w-0">
                  <p className="text-xs font-medium text-foreground leading-tight truncate">{role.title || "Untitled Role"}</p>
                  {role.company && (
                    <p className="text-[11px] text-muted-foreground truncate">{role.company}</p>
                  )}
                  <div className="flex items-center gap-1.5 flex-wrap">
                    {duration && <span className="text-[10px] text-muted-foreground">{duration}</span>}
                    {isCurrentRole && (
                      <Badge variant="outline" className="text-[9px] h-4 bg-emerald-500/10 text-emerald-600 border-emerald-200">Current</Badge>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
          {roles.length > 4 && (
            <p className="text-[10px] text-muted-foreground">+{roles.length - 4} more roles</p>
          )}
        </div>
      ) : (
        <p className="text-xs text-muted-foreground">No experience data available</p>
      )}
    </div>
  );
};

export default ExperiencePanel;

