import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import { XCircle } from "lucide-react";
import { STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";
import { format } from "date-fns";

interface StageTrackerProps {
  currentStage: HiringStage;
  updatedAt?: string | null;
  onStageChange: (stage: HiringStage) => void;
  disabled?: boolean;
}

const STAGE_LABELS: Record<string, string> = {
  applied: "Applied",
  screened: "Screened",
  interview: "Interview",
  offer: "Offer",
  hired: "Hired",
};

const StageTracker = ({ currentStage, updatedAt, onStageChange, disabled }: StageTrackerProps) => {
  const currentIndex = currentStage === "rejected" ? -1 : STAGE_ORDER.indexOf(currentStage);
  const isRejected = currentStage === "rejected";

  return (
    <div className="flex items-center gap-2">
      <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider shrink-0">Stage</span>

      <div className="flex items-center gap-0 flex-1 min-w-0">
        {STAGE_ORDER.map((stage, i) => {
          const isCompleted = !isRejected && i < currentIndex;
          const isCurrent = !isRejected && i === currentIndex;
          const isUpcoming = isRejected || i > currentIndex;

          return (
            <div key={stage} className="flex items-center">
              {/* Dot */}
              <TooltipProvider delayDuration={200}>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      disabled={disabled}
                      onClick={(e) => {
                        e.stopPropagation();
                        onStageChange(stage);
                      }}
                      className={cn(
                        "w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-bold transition-all shrink-0",
                        "focus:outline-none focus:ring-2 focus:ring-primary/30",
                        isCompleted && "bg-emerald-500 text-white",
                        isCurrent && "bg-primary text-white ring-2 ring-primary/30",
                        isUpcoming && "bg-muted border border-border text-muted-foreground",
                        !disabled && "cursor-pointer hover:scale-110",
                        disabled && "cursor-default"
                      )}
                    >
                      {isCompleted ? "✓" : i + 1}
                    </button>
                  </TooltipTrigger>
                  <TooltipContent className="text-xs">
                    {isCompleted ? `${STAGE_LABELS[stage]} (done)` : isCurrent ? `${STAGE_LABELS[stage]} (current)` : `Move to ${STAGE_LABELS[stage]}`}
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>

              {/* Connector line */}
              {i < STAGE_ORDER.length - 1 && (
                <div
                  className={cn(
                    "h-0.5 w-6 sm:w-8 transition-all",
                    i < currentIndex && !isRejected ? "bg-emerald-500" : "bg-border"
                  )}
                />
              )}
            </div>
          );
        })}
      </div>

      {/* Labels row - shown below on small screens, inline on larger */}
      <div className="hidden sm:flex items-center gap-1">
        {/* Reject button */}
        <TooltipProvider delayDuration={200}>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                disabled={disabled}
                className={cn(
                  "h-6 w-6",
                  isRejected ? "text-destructive" : "text-muted-foreground/50 hover:text-destructive"
                )}
                onClick={(e) => {
                  e.stopPropagation();
                  onStageChange("rejected");
                }}
              >
                <XCircle className="h-3.5 w-3.5" />
              </Button>
            </TooltipTrigger>
            <TooltipContent className="text-xs">Reject candidate</TooltipContent>
          </Tooltip>
        </TooltipProvider>
      </div>

      {/* Rejected badge */}
      {isRejected && (
        <Badge variant="destructive" className="text-[10px] shrink-0">Rejected</Badge>
      )}

      {/* Updated timestamp */}
      {updatedAt && (
        <span className="text-[10px] text-muted-foreground shrink-0 hidden sm:inline">
          Updated {format(new Date(updatedAt), "MMM d")}
        </span>
      )}
    </div>
  );
};

export default StageTracker;

import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle, FileCheck, Lightbulb } from "lucide-react";
import type { Result } from "@/pages/Index";

interface JDAlignedPanelProps {
  result: Result;
}

const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
  const matched = (r.matched_must_haves as string[]) || [];
  const missing = (r.missing_must_haves as string[]) || [];
  const total = matched.length + missing.length;
  const metPercent = total > 0 ? Math.round((matched.length / total) * 100) : 0;

  if (total === 0 && !r.explanation_json?.why_ranked_here) return null;

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-6 h-6 rounded bg-score-jd/10 flex items-center justify-center">
          <FileCheck className="h-3.5 w-3.5 text-score-jd" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">JD Aligned</h4>
        {total > 0 && (
          <Badge variant="outline" className="ml-auto text-[10px]">
            {matched.length} of {total} met · {metPercent}%
          </Badge>
        )}
      </div>

      {total > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          {/* Must Have - Met */}
          {matched.length > 0 && (
            <div className="space-y-1.5">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Must Have</span>
              {matched.map((item, i) => (
                <div key={i} className="flex items-start gap-1.5 text-xs">
                  <CheckCircle2 className="h-3.5 w-3.5 text-success shrink-0 mt-0.5" />
                  <span className="text-foreground">{item}</span>
                  <Badge variant="outline" className="ml-auto text-[9px] shrink-0 bg-emerald-500/10 text-emerald-600 border-emerald-200">Met</Badge>
                </div>
              ))}
            </div>
          )}

          {/* Critical Gaps */}
          {missing.length > 0 && (
            <div className="space-y-1.5">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Critical Gaps</span>
              {missing.map((item, i) => (
                <div key={i} className="flex items-start gap-1.5 text-xs">
                  <XCircle className="h-3.5 w-3.5 text-destructive shrink-0 mt-0.5" />
                  <span className="text-muted-foreground">{item}</span>
                  <Badge variant="outline" className="ml-auto text-[9px] shrink-0 bg-red-500/10 text-red-600 border-red-200">Gap</Badge>
                </div>
              ))}
            </div>
          )}

          {/* AI Insight */}
          {r.explanation_json?.why_ranked_here && (
            <div className="space-y-1.5">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">AI Insight</span>
              <div className="p-2 rounded bg-score-overall/5 border border-score-overall/20">
                <div className="flex items-start gap-1.5">
                  <Lightbulb className="h-3.5 w-3.5 text-score-overall shrink-0 mt-0.5" />
                  <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default JDAlignedPanel;

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCell, TableRow } from "@/components/ui/table";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
import {
  ChevronDown, ChevronUp, Phone, Mail, MapPin,
  FileText, Archive
} from "lucide-react";
import { toast } from "sonner";
import type { Result } from "@/pages/Index";
import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";

// Sub-components
import CandidateSummary from "@/components/candidate/CandidateSummary";
import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
import ExperiencePanel from "@/components/candidate/ExperiencePanel";
import EducationPanel from "@/components/candidate/EducationPanel";
import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
import AINudgePanel from "@/components/candidate/AINudgePanel";
import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
import StageTracker from "@/components/candidate/StageTracker";
import type { HiringStage } from "@/hooks/useStageTracker";

interface CandidateRowProps {
  result: Result;
  index: number;
  isExpanded: boolean;
  isSelected: boolean;
  jobTitle?: string | null;
  onToggleRow: (id: string) => void;
  onToggleSelect: (resumeId: string) => void;
  onDownload: (filePath: string, filename: string) => void;
  onDelete: (resumeId: string, filePath: string | null) => void;
  onDismiss: (resumeId: string) => void;
  formatCandidateName: (filename: string) => string;
  currentStage?: HiringStage | null;
  stageUpdatedAt?: string | null;
  onStageChange?: (resumeId: string, stage: HiringStage) => void;
}

const getScoreColor = (score: number) => {
  if (score >= 70) return "bg-score-skills";
  if (score >= 40) return "bg-warning";
  return "bg-destructive";
};

const getScoreTextColor = (score: number) => {
  if (score >= 70) return "text-score-skills";
  if (score >= 40) return "text-warning";
  return "text-destructive";
};

const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
  if (score >= 70) return { label: "Strong", variant: "success" };
  if (score >= 40) return { label: "Good", variant: "warning" };
  return { label: "Weak", variant: "destructive" };
};

const getRankDisplay = (index: number) => {
  if (index < 3) {
    const colors = [
      "bg-score-overall text-white",
      "bg-muted-foreground/60 text-white",
      "bg-warning text-white",
    ];
    return (
      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
        {index + 1}
      </span>
    );
  }
  return (
    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
      {index + 1}
    </span>
  );
};

const CandidateRow = ({
  result: r,
  index,
  isExpanded,
  isSelected,
  jobTitle,
  onToggleRow,
  onToggleSelect,
  onDownload,
  onDelete,
  onDismiss,
  formatCandidateName,
  currentStage,
  stageUpdatedAt,
  onStageChange,
}: CandidateRowProps) => {
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;

  return (
    <>
    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
      <>
        {/* Collapsed Row */}
        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
          <TableCell onClick={(e) => e.stopPropagation()}>
            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
          </TableCell>
          <TableCell className="text-center">
            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
          </TableCell>
          <TableCell className="font-medium">
            <div className="flex flex-col">
              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
              {r.candidate_location && (
                <span className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
                  <MapPin className="h-3 w-3" /> {r.candidate_location}
                </span>
              )}
            </div>
          </TableCell>
          <TableCell>
            {r.pending ? (
              <Badge variant="outline" className="text-xs">Pending</Badge>
            ) : (
              <div className="flex items-center gap-2">
                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
                  <div
                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
                  />
                </div>
                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
                  {r.overall_score?.toFixed(0)}%
                </span>
              </div>
            )}
          </TableCell>
          <TableCell>
            <div className="flex flex-wrap items-center gap-1">
              {!r.pending && strength && (
                <Badge variant={strength.variant} className="text-[10px]">
                  {strength.label}
                </Badge>
              )}
              {!r.pending && currentStage && currentStage !== "applied" && (
                <Badge variant="outline" className="text-[10px] capitalize">
                  {currentStage}
                </Badge>
              )}
              {!r.pending && r.scoring_version === "heuristic" && (
                <TooltipProvider delayDuration={300}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
                        Quick
                      </span>
                    </TooltipTrigger>
                    <TooltipContent className="max-w-xs text-xs">
                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              )}
            </div>
          </TableCell>
          <TableCell>
            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
              <TooltipProvider delayDuration={300}>
                {/* Phone */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.candidate_phone ? (
                      <a
                        href={`tel:${r.candidate_phone}`}
                        onClick={(e) => {
                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
                            e.preventDefault();
                            navigator.clipboard.writeText(r.candidate_phone!);
                            toast.success("Phone number copied!");
                          }
                        }}
                      >
                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
                          <Phone className="h-3.5 w-3.5" />
                        </Button>
                      </a>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Phone className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_phone ? (/Mobi|Android/i.test(navigator.userAgent) ? r.candidate_phone : "Copy phone") : "No phone"}</TooltipContent>
                </Tooltip>

                {/* Email */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.candidate_email ? (
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 text-muted-foreground hover:text-primary"
                        onClick={() => setEmailDialogOpen(true)}
                      >
                        <Mail className="h-3.5 w-3.5" />
                      </Button>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <Mail className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.candidate_email ? "Send email" : "No email"}</TooltipContent>
                </Tooltip>

                {/* Download */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    {r.file_path ? (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
                        <FileText className="h-3.5 w-3.5" />
                      </Button>
                    ) : (
                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
                        <FileText className="h-3.5 w-3.5" />
                      </Button>
                    )}
                  </TooltipTrigger>
                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
                </Tooltip>

                {/* Archive */}
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Button
                      variant="ghost" size="icon"
                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
                      onClick={() => onDismiss(r.resume_id)}
                    >
                      <Archive className="h-3.5 w-3.5" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent>Archive candidate</TooltipContent>
                </Tooltip>
              </TooltipProvider>

              {!r.pending && (
                <CollapsibleTrigger asChild>
