528→        for (const mh of mustHaves) {
529→          if (fuzzyMatch(mh, allResumeTerms)) {
530→            matchedCount++;
531→            matchedSkills.push(mh);
532→          } else {
533→            missingSkills.push(mh);
534→          }
535→        }
536→        for (const tool of jdTools) {
537→          if (fuzzyMatch(tool, allResumeTerms)) {
538→            matchedCount++;
539→            matchedSkills.push(tool);
540→          }
541→        }
542→
543→        const keywordScore = totalKeywords > 0 ? (matchedCount / totalKeywords) * 100 : 50;
544→        const similarity = similarityMap.get(resume.id) ?? 0.5;
545→        const similarityScore = similarity * 100;
546→
547→        let overallScore = Math.round(similarityScore * 0.6 + keywordScore * 0.4);
548→
549→        // Hard fit cap: if missing critical must-haves
550→        let hardFit = missingSkills.length === 0;
551→        if (!hardFit) {
552→          overallScore = Math.min(overallScore, 49);
553→        }
554→        overallScore = Math.max(0, Math.min(100, overallScore));
555→
556→        const summary = `Ranked by resume similarity (${Math.round(similarityScore)}%). Matched: ${matchedSkills.slice(0, 5).join(', ') || 'none'}. Missing: ${missingSkills.slice(0, 5).join(', ') || 'none'}.`;
557→
558→        // Update resume status
559→        await supabase.from("resumes").update({ status: "done" }).eq("id", resume.id);
560→
561→        // Upsert heuristic result
562→        const { data: existingResult } = await supabase
563→          .from("results")
564→          .select("id")
565→          .eq("resume_id", resume.id)
566→          .limit(1)
567→          .single();
568→
569→        const resultData = {
