import { Badge } from "@/components/ui/badge";
import { CheckCircle2, XCircle, FileCheck, Lightbulb } from "lucide-react";
import type { Result } from "@/pages/Index";

interface JDAlignedPanelProps {
  result: Result;
}

const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
  const matched = (r.matched_must_haves as string[]) || [];
  const missing = (r.missing_must_haves as string[]) || [];
  const total = matched.length + missing.length;
  const metPercent = total > 0 ? Math.round((matched.length / total) * 100) : 0;

  if (total === 0 && !r.explanation_json?.why_ranked_here) return null;

  return (
    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
      <div className="flex items-center gap-2 mb-1">
        <div className="w-6 h-6 rounded bg-score-jd/10 flex items-center justify-center">
          <FileCheck className="h-3.5 w-3.5 text-score-jd" />
        </div>
        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">JD Aligned</h4>
        {total > 0 && (
          <Badge variant="outline" className="ml-auto text-[10px]">
            {matched.length} of {total} met · {metPercent}%
          </Badge>
        )}
      </div>

      {total > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {/* Must Have - Met */}
          {matched.length > 0 && (
            <div className="space-y-1.5">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Must Have</span>
              {matched.map((item, i) => (
                <div key={i} className="flex items-start gap-1.5 text-xs">
                  <CheckCircle2 className="h-3.5 w-3.5 text-success shrink-0 mt-0.5" />
                  <span className="text-foreground">{item}</span>
                  <Badge variant="outline" className="ml-auto text-[9px] shrink-0 bg-emerald-500/10 text-emerald-600 border-emerald-200">Met</Badge>
                </div>
              ))}
            </div>
          )}

          {/* Critical Gaps */}
          {missing.length > 0 && (
            <div className="space-y-1.5">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Critical Gaps</span>
              {missing.map((item, i) => (
                <div key={i} className="flex items-start gap-1.5 text-xs">
                  <XCircle className="h-3.5 w-3.5 text-destructive shrink-0 mt-0.5" />
                  <span className="text-muted-foreground">{item}</span>
                  <Badge variant="outline" className="ml-auto text-[9px] shrink-0 bg-red-500/10 text-red-600 border-red-200">Gap</Badge>
                </div>
              ))}
            </div>
          )}

          {/* AI Insight */}
          {r.explanation_json?.why_ranked_here && (
            <div className="space-y-1.5">
              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">AI Insight</span>
              <div className="p-2 rounded bg-score-overall/5 border border-score-overall/20">
                <div className="flex items-start gap-1.5">
                  <Lightbulb className="h-3.5 w-3.5 text-score-overall shrink-0 mt-0.5" />
                  <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default JDAlignedPanel;

