            <p className="text-xs text-muted-foreground leading-relaxed">{tradeoffs}</p>
          )}
          {confidence < 70 && (
            <p className="text-xs text-muted-foreground leading-relaxed">
              Confidence: {confidence.toFixed(0)}% — {confidence < 40 ? "Low confidence. Resume may lack detail for accurate scoring." : "Medium confidence. Some scoring dimensions had limited evidence."}
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

export default AINudgePanel;

