 1→import { Badge } from "@/components/ui/badge";
 2→import { Briefcase } from "lucide-react";
 3→
 4→interface Role {
 5→  title?: string;
 6→  company?: string;
 7→  start?: string;
 8→  end?: string;
 9→  description?: string;
10→}
11→
12→interface ExperiencePanelProps {
13→  parsedJson: any;
14→}
15→
16→const ExperiencePanel = ({ parsedJson }: ExperiencePanelProps) => {
17→  const roles: Role[] = parsedJson?.roles_with_dates || parsedJson?.experience || [];
18→  const extractYear = (dateStr?: string): number | null => {
19→    if (!dateStr) return null;
20→    const match = dateStr.match(/\b(19|20)\d{2}\b/);
21→    return match ? parseInt(match[0]) : null;
22→  };
23→
24→  const totalYears = roles.length > 0
25→    ? roles.reduce((sum, r) => {
26→        const startYear = extractYear(r.start);
27→        if (!startYear) return sum;
28→        const isCurrentRole = r.end?.toLowerCase() === "current" || r.end?.toLowerCase() === "present";
29→        const endYear = isCurrentRole ? new Date().getFullYear() : extractYear(r.end);
30→        if (!endYear) return sum;
31→        return sum + Math.max(0, endYear - startYear);
32→      }, 0)
33→    : null;
34→
35→  return (
36→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
37→      <div className="flex items-center gap-2 mb-1">
38→        <div className="w-6 h-6 rounded bg-purple-500/10 flex items-center justify-center">
39→          <Briefcase className="h-3.5 w-3.5 text-purple-500" />
40→        </div>
41→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Experience</h4>
42→        {totalYears !== null && totalYears > 0 && (
43→          <Badge variant="outline" className="ml-auto text-[10px]">{totalYears} yrs</Badge>
44→        )}
45→      </div>
46→
47→      {roles.length > 0 ? (
48→        <div className="space-y-3">
49→          {roles.slice(0, 4).map((role, i) => {
50→            const duration = role.start && role.end
51→              ? `${role.start} – ${role.end}`
52→              : role.start || "";
53→            const isCurrentRole = role.end?.toLowerCase() === "current" || role.end?.toLowerCase() === "present";
54→
55→            return (
56→              <div key={i} className="flex gap-2">
57→                <div className="flex flex-col items-center mt-1">
58→                  <div className={`w-2 h-2 rounded-full shrink-0 ${i === 0 ? "bg-purple-500" : "bg-muted-foreground/40"}`} />
59→                  {i < Math.min(roles.length, 4) - 1 && <div className="w-px flex-1 bg-border mt-1" />}
60→                </div>
61→                <div className="space-y-0.5 min-w-0">
62→                  <p className="text-xs font-medium text-foreground leading-tight truncate">{role.title || "Untitled Role"}</p>
63→                  {role.company && (
64→                    <p className="text-[11px] text-muted-foreground truncate">{role.company}</p>
65→                  )}
66→                  <div className="flex items-center gap-1.5 flex-wrap">
67→                    {duration && <span className="text-[10px] text-muted-foreground">{duration}</span>}
68→                    {isCurrentRole && (
69→                      <Badge variant="outline" className="text-[9px] h-4 bg-emerald-500/10 text-emerald-600 border-emerald-200">Current</Badge>
70→                    )}
71→                  </div>
72→                </div>
73→              </div>
74→            );
75→          })}
76→          {roles.length > 4 && (
77→            <p className="text-[10px] text-muted-foreground">+{roles.length - 4} more roles</p>
78→          )}
79→        </div>
80→      ) : (
81→        <p className="text-xs text-muted-foreground">No experience data available</p>
82→      )}
83→    </div>
84→  );
85→};
86→
87→export default ExperiencePanel;
