 1→import { Badge } from "@/components/ui/badge";
 2→import { GraduationCap } from "lucide-react";
 3→
 4→interface Education {
 5→  degree?: string;
 6→  institution?: string;
 7→  year?: string;
 8→}
 9→
10→interface EducationPanelProps {
11→  parsedJson: any;
12→  matchedMustHaves?: string[];
13→}
14→
15→const EducationPanel = ({ parsedJson, matchedMustHaves }: EducationPanelProps) => {
16→  const education: Education[] = parsedJson?.education || [];
17→  const certifications: string[] = parsedJson?.certifications || [];
18→  const matchedLower = (matchedMustHaves || []).map((m: string) => m.toLowerCase());
19→
20→  const getRelevanceChip = (degree: string, institution: string) => {
21→    const combined = `${degree} ${institution}`.toLowerCase();
22→    // Only match if specific must-have text overlaps with degree/institution (not generic keywords)
23→    const isMatched = matchedLower.some((m) => {
24→      const words = m.split(/\s+/).filter((w) => w.length > 3);
25→      return words.some((w) => combined.includes(w));
26→    });
27→    if (isMatched) return { label: "JD Match", color: "bg-emerald-500/10 text-emerald-600 border-emerald-200" };
28→    if (degree) return { label: "Relevant", color: "bg-blue-500/10 text-blue-600 border-blue-200" };
29→    return null;
30→  };
31→
32→  const matchCount = education.filter((e) => {
33→    const chip = getRelevanceChip(e.degree || "", e.institution || "");
34→    return chip?.label === "JD Match";
35→  }).length;
36→
37→  return (
38→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
39→      <div className="flex items-center gap-2 mb-1">
40→        <div className="w-6 h-6 rounded bg-score-education/10 flex items-center justify-center">
41→          <GraduationCap className="h-3.5 w-3.5 text-score-education" />
42→        </div>
43→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">Education</h4>
44→        {matchCount > 0 && (
45→          <Badge variant="outline" className="ml-auto text-[10px]">{matchCount} matched</Badge>
46→        )}
47→      </div>
48→
49→      {education.length > 0 ? (
50→        <div className="space-y-3">
51→          {education.slice(0, 4).map((edu, i) => {
52→            const chip = getRelevanceChip(edu.degree || "", edu.institution || "");
53→            return (
54→              <div key={i} className="space-y-0.5">
55→                <div className="flex items-start gap-1.5">
56→                  <GraduationCap className="h-3 w-3 text-muted-foreground shrink-0 mt-0.5" />
57→                  <div className="min-w-0">
58→                    <p className="text-xs font-medium text-foreground leading-tight">{edu.degree || "Degree"}</p>
59→                    {edu.institution && (
60→                      <p className="text-[11px] text-muted-foreground truncate">{edu.institution}</p>
61→                    )}
62→                    <div className="flex items-center gap-1.5 mt-0.5">
63→                      {edu.year && <span className="text-[10px] text-muted-foreground">{edu.year}</span>}
64→                      {chip && (
65→                        <span className={`text-[9px] font-medium px-1.5 py-0.5 rounded border ${chip.color}`}>
66→                          {chip.label}
67→                        </span>
68→                      )}
69→                    </div>
70→                  </div>
71→                </div>
72→              </div>
73→            );
74→          })}
75→        </div>
76→      ) : (
77→        <p className="text-xs text-muted-foreground">No education data available</p>
78→      )}
79→
80→      {certifications.length > 0 && (
81→        <div className="pt-1 space-y-1">
82→          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Certifications</span>
83→          <div className="flex flex-wrap gap-1">
84→            {certifications.slice(0, 4).map((cert, i) => (
85→              <Badge key={i} variant="outline" className="text-[10px]">{cert}</Badge>
86→            ))}
87→          </div>
88→        </div>
89→      )}
90→    </div>
91→  );
92→};
93→
94→export default EducationPanel;
