 1→import { Badge } from "@/components/ui/badge";
 2→import { CheckCircle2, XCircle, FileCheck, Lightbulb } from "lucide-react";
 3→import type { Result } from "@/pages/Index";
 4→
 5→interface JDAlignedPanelProps {
 6→  result: Result;
 7→}
 8→
 9→const JDAlignedPanel = ({ result: r }: JDAlignedPanelProps) => {
10→  const matched = (r.matched_must_haves as string[]) || [];
11→  const missing = (r.missing_must_haves as string[]) || [];
12→  const total = matched.length + missing.length;
13→  const metPercent = total > 0 ? Math.round((matched.length / total) * 100) : 0;
14→
15→  if (total === 0 && !r.explanation_json?.why_ranked_here) return null;
16→
17→  return (
18→    <div className="rounded-lg border border-border bg-card p-4 space-y-3">
19→      <div className="flex items-center gap-2 mb-1">
20→        <div className="w-6 h-6 rounded bg-score-jd/10 flex items-center justify-center">
21→          <FileCheck className="h-3.5 w-3.5 text-score-jd" />
22→        </div>
23→        <h4 className="text-xs font-semibold text-foreground uppercase tracking-wide">JD Aligned</h4>
24→        {total > 0 && (
25→          <Badge variant="outline" className="ml-auto text-[10px]">
26→            {matched.length} of {total} met · {metPercent}%
27→          </Badge>
28→        )}
29→      </div>
30→
31→      {total > 0 && (
32→        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
33→          {/* Must Have - Met */}
34→          {matched.length > 0 && (
35→            <div className="space-y-1.5">
36→              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Must Have</span>
37→              {matched.map((item, i) => (
38→                <div key={i} className="flex items-start gap-1.5 text-xs">
39→                  <CheckCircle2 className="h-3.5 w-3.5 text-success shrink-0 mt-0.5" />
40→                  <span className="text-foreground">{item}</span>
41→                  <Badge variant="outline" className="ml-auto text-[9px] shrink-0 bg-emerald-500/10 text-emerald-600 border-emerald-200">Met</Badge>
42→                </div>
43→              ))}
44→            </div>
45→          )}
46→
47→          {/* Critical Gaps */}
48→          {missing.length > 0 && (
49→            <div className="space-y-1.5">
50→              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">Critical Gaps</span>
51→              {missing.map((item, i) => (
52→                <div key={i} className="flex items-start gap-1.5 text-xs">
53→                  <XCircle className="h-3.5 w-3.5 text-destructive shrink-0 mt-0.5" />
54→                  <span className="text-muted-foreground">{item}</span>
55→                  <Badge variant="outline" className="ml-auto text-[9px] shrink-0 bg-red-500/10 text-red-600 border-red-200">Gap</Badge>
56→                </div>
57→              ))}
58→            </div>
59→          )}
60→
61→          {/* AI Insight */}
62→          {r.explanation_json?.why_ranked_here && (
63→            <div className="space-y-1.5">
64→              <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-medium">AI Insight</span>
65→              <div className="p-2 rounded bg-score-overall/5 border border-score-overall/20">
66→                <div className="flex items-start gap-1.5">
67→                  <Lightbulb className="h-3.5 w-3.5 text-score-overall shrink-0 mt-0.5" />
68→                  <p className="text-[11px] text-muted-foreground leading-relaxed">{r.explanation_json.why_ranked_here}</p>
69→                </div>
70→              </div>
71→            </div>
72→          )}
73→        </div>
74→      )}
75→    </div>
76→  );
77→};
78→
79→export default JDAlignedPanel;
