 8→const StrengthsGapsPanel = ({ result: r }: StrengthsGapsPanelProps) => {
 9→  const strengths = (r.strengths_json || r.matched_must_haves || []) as string[];
10→  const gaps = (r.gaps_json || r.missing_must_haves || r.missing_skills || []) as string[];
11→
12→  if (strengths.length === 0 && gaps.length === 0) return null;
13→
14→  return (
15→    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
