20→            <CheckCircle2 className="h-3.5 w-3.5" /> Strengths
21→          </h5>
22→          <div className="space-y-1.5">
23→            {strengths.slice(0, 6).map((s, i) => (
24→              <div key={i} className="flex items-center gap-2 text-xs px-2.5 py-1.5 rounded-md bg-success/5 border border-success/15 text-foreground">
25→                <CheckCircle2 className="h-3 w-3 text-success shrink-0" />
26→                {s}
27→              </div>
28→            ))}
29→          </div>
30→        </div>
31→      )}
32→      {/* Gaps */}
33→      {gaps.length > 0 && (
34→        <div className="space-y-2">
35→          <h5 className="text-xs font-semibold text-destructive uppercase tracking-wide flex items-center gap-1">
