import { Card, CardContent } from "@/components/ui/card";
import { Target, ShieldCheck, BarChart3, TrendingUp } from "lucide-react";
import type { Result } from "@/pages/Index";

interface ScoreSummaryCardsProps {
  results: Result[];
}

const ScoreSummaryCards = ({ results }: ScoreSummaryCardsProps) => {
  const scored = results.filter((r) => !r.pending && r.overall_score > 0);
  if (scored.length === 0) return null;

  const avg = (fn: (r: Result) => number) =>
    Math.round(scored.reduce((sum, r) => sum + fn(r), 0) / scored.length);

  // Compute avg category score from category_scores_json (the actual dynamic scores)
  const avgCategoryScore = (r: Result): number => {
    if (!r.category_scores_json || typeof r.category_scores_json !== "object") return 0;
    const entries = Object.values(r.category_scores_json as Record<string, { score: number }>);
    if (entries.length === 0) return 0;
    return entries.reduce((sum, e) => sum + (e.score ?? 0), 0) / entries.length;
  };

  // Compute JD match % from matched vs total must-haves
  const jdMatchPercent = (r: Result): number => {
    const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.length : 0;
    const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.length : 0;
    const total = matched + missing;
    if (total === 0) return 0;
    return Math.round((matched / total) * 100);
  };

  const cards = [
    {
      label: "Overall Match",
      value: avg((r) => r.overall_score),
      icon: Target,
      color: "bg-score-overall",
      textColor: "text-score-overall",
      bgLight: "bg-score-overall/10",
    },
    {
      label: "Avg Skill Score",
      value: avg(avgCategoryScore),
      icon: BarChart3,
      color: "bg-score-skills",
      textColor: "text-score-skills",
      bgLight: "bg-score-skills/10",
    },
    {
      label: "Confidence",
      value: avg((r) => r.confidence ?? 0),
      icon: TrendingUp,
      color: "bg-score-education",
      textColor: "text-score-education",
      bgLight: "bg-score-education/10",
    },
    {
      label: "JD Alignment",
      value: avg(jdMatchPercent),
      icon: ShieldCheck,
      color: "bg-score-jd",
      textColor: "text-score-jd",
      bgLight: "bg-score-jd/10",
    },
  ];

  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
      {cards.map((card) => (
        <Card key={card.label} className="overflow-hidden">
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-3">
              <div className={`w-8 h-8 rounded-lg ${card.bgLight} flex items-center justify-center`}>
                <card.icon className={`h-4 w-4 ${card.textColor}`} />
              </div>
              <span className="text-xs font-medium text-muted-foreground">{card.label}</span>
            </div>
            <div className="flex items-end gap-1 mb-2">
              <span className={`text-2xl font-bold tabular-nums ${card.textColor}`}>
                {card.value}
              </span>
              <span className="text-sm text-muted-foreground mb-0.5">%</span>
            </div>
            <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
              <div
                className={`h-full rounded-full transition-all duration-500 ${card.color}`}
                style={{ width: `${Math.min(card.value, 100)}%` }}
              />
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
};

export default ScoreSummaryCards;

