329→      }
330→    }
331→
332→    // ─── STEP 4: Heuristic rerank to top 20 ──────────────────────
333→    let top20Ids = shortlistedIds;
334→    if (shortlistedIds.length > 20) {
335→      console.log("Heuristic reranking to top 20...");
336→      const { data: shortlistedResumes } = await supabase
337→        .from("resumes")
338→        .select("id, parsed_json")
339→        .in("id", shortlistedIds);
340→
341→      if (shortlistedResumes) {
342→        const scored = shortlistedResumes.map((r: any) => {
343→          let score = 0;
344→          const mustHaves = jdAnalysis.critical_must_haves || [];
345→          const tools = jdAnalysis.tools || [];
346→          const allResumeTerms = extractResumeTerms(r.parsed_json);
347→
348→          for (const mh of mustHaves) {
349→            if (fuzzyMatch(mh, allResumeTerms)) score += 3;
350→          }
351→          for (const tool of tools) {
352→            if (fuzzyMatch(tool, allResumeTerms)) score += 1;
353→          }
354→
355→          // Preferred must-haves (lower weight)
356→          const preferred = jdAnalysis.preferred_must_haves || [];
357→          for (const pref of preferred) {
358→            if (fuzzyMatch(pref, allResumeTerms)) score += 1.5;
359→          }
360→
361→          // Years estimate
362→          const roles = (r.parsed_json || {}).roles_with_dates || [];
363→          if (roles.length > 0) score += Math.min(roles.length, 5);
364→
365→          return { id: r.id, score };
366→        });
367→
368→        scored.sort((a, b) => b.score - a.score);
369→        top20Ids = scored.slice(0, 20).map((s) => s.id);
370→      }
371→    }
372→
373→    // ─── STEP 5: Deep score top 20 ───────────────────────────────
374→    console.log(`Deep scoring ${top20Ids.length} resumes...`);
375→    const dimensions = jdAnalysis.evaluation_dimensions || [];
376→    let successCount = 0;
377→    let failCount = 0;
378→
379→    // Process in parallel batches of 5
380→    const batchSize = 5;
381→    for (let i = 0; i < top20Ids.length; i += batchSize) {
382→      const batch = top20Ids.slice(i, i + batchSize);
383→      const promises = batch.map(async (rid) => {
384→        const { data: resume } = await supabase
385→          .from("resumes")
386→          .select("id, filename, parsed_json, parsed_text, candidate_name")
387→          .eq("id", rid)
388→          .single();
389→        if (!resume) return;
390→
391→        try {
392→          const resumeText = resume.parsed_text || JSON.stringify(resume.parsed_json || {});
393→          const deepResult = await deepScoreResume(
394→            job.job_description,
395→            resumeText,
396→            resume.parsed_json,
397→            jdAnalysis,
398→            dimensions,
399→            cfg,
400→            deepScoringPrompt
401→          );
402→
403→          // Compute overall score deterministically
404→          let overallScore = 0;
405→          const categoryScores = deepResult.category_scores || {};
406→          for (const dim of dimensions) {
407→            const dimScore = categoryScores[dim.key]?.score ?? 0;
408→            const weight = dynamicWeights[dim.key] ?? 0;
409→            overallScore += dimScore * weight;
410→          }
411→          overallScore = Math.round(overallScore * 100) / 100;
412→
413→          // Hard fit cap
414→          let hardFit = deepResult.hard_fit !== false;
415→          const missingCritical = deepResult.missing_critical_must_haves || [];
416→          if (missingCritical.length > 0) {
417→            hardFit = false;
418→            overallScore = Math.min(overallScore, 49);
419→          }
420→
421→          // Update candidate name
422→          if (deepResult.candidate_name && deepResult.candidate_name !== "Unknown Candidate") {
423→            await supabase.from("resumes").update({
424→              candidate_name: deepResult.candidate_name,
425→              status: "done",
426→            }).eq("id", rid);
427→          } else {
428→            await supabase.from("resumes").update({ status: "done" }).eq("id", rid);
429→          }
430→
431→          // Upsert result
432→          // Check if result exists for this resume
433→          const { data: existingResult } = await supabase
434→            .from("results")
435→            .select("id")
436→            .eq("resume_id", rid)
437→            .limit(1)
438→            .single();
439→
440→          const resultData = {
441→            resume_id: rid,
442→            job_id: job_id,
443→            scoring_version: CURRENT_PARSE_VERSION,
444→            overall_score: overallScore,
445→            hard_fit: hardFit,
446→            confidence: deepResult.confidence ?? 0,
447→            category_scores_json: categoryScores,
448→            strengths_json: deepResult.strengths || [],
449→            gaps_json: deepResult.gaps || [],
450→            interview_questions: deepResult.interview_questions || [],
451→            explanation_json: deepResult.explanation || {},
452→            matched_must_haves: deepResult.matched_critical_must_haves || [],
453→            missing_must_haves: missingCritical,
454→            missing_skills: missingCritical,
455→            summary: deepResult.explanation?.summary || "",
456→            // Keep old columns null for new scoring
457→            skill_score: null,
458→            experience_score: null,
459→            education_score: null,
460→          };
461→
462→          if (existingResult) {
463→            await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
464→          } else {
465→            await supabase.from("results").insert(resultData as any);
466→          }
467→
468→          successCount++;
469→          console.log(`Resume ${rid} scored: overall=${overallScore}, hardFit=${hardFit}`);
470→        } catch (err) {
471→          failCount++;
472→          console.error(`Error scoring resume ${rid}:`, err);
473→          await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
474→          // Insert failed result
475→          const { data: existingResult } = await supabase.from("results").select("id").eq("resume_id", rid).limit(1).single();
476→          if (!existingResult) {
477→            await supabase.from("results").insert({
478→              resume_id: rid,
479→              job_id: job_id,
480→              overall_score: 0,
481→              hard_fit: false,
482→              confidence: 0,
483→              category_scores_json: {},
484→              strengths_json: [],
485→              gaps_json: [],
486→              summary: `Scoring failed: ${err instanceof Error ? err.message : "Unknown error"}`,
487→            } as any);
488→          }
489→        }
490→      });
491→
492→      await Promise.all(promises);
493→    }
494→
495→    // ─── STEP 6: Heuristic score remaining resumes ─────────────
496→    const unscoredIds = targetResumeIds.filter((id) => !top20Ids.includes(id));
497→    if (unscoredIds.length > 0) {
498→      console.log(`Heuristic scoring ${unscoredIds.length} remaining resumes...`);
499→
500→      // Get all similarity scores (covering all resumes, not just top 50)
