511→          }
512→        }
513→      }
514→
515→      // Fetch parsed data for unscored resumes
516→      const { data: unscoredResumes } = await supabase
517→        .from("resumes")
518→        .select("id, parsed_json, candidate_name")
519→        .in("id", unscoredIds);
520→
521→      const mustHaves = jdAnalysis.critical_must_haves || [];
522→      const jdTools = jdAnalysis.tools || [];
523→
524→      for (const resume of (unscoredResumes || [])) {
525→        const allResumeTerms = extractResumeTerms(resume.parsed_json);
526→
527→        // Keyword overlap score (0-100)
528→        const totalKeywords = mustHaves.length + jdTools.length;
529→        let matchedCount = 0;
530→        const matchedSkills: string[] = [];
531→        const missingSkills: string[] = [];
532→
533→        for (const mh of mustHaves) {
