561→        const summary = `Ranked by resume similarity (${Math.round(similarityScore)}%). Matched: ${matchedSkills.slice(0, 5).join(', ') || 'none'}. Missing: ${missingSkills.slice(0, 5).join(', ') || 'none'}.`;
562→
563→        // Update resume status
564→        await supabase.from("resumes").update({ status: "done" }).eq("id", resume.id);
565→
566→        // Upsert heuristic result
567→        const { data: existingResult } = await supabase
568→          .from("results")
569→          .select("id")
570→          .eq("resume_id", resume.id)
571→          .limit(1)
572→          .single();
573→
574→        // Compute heuristic confidence from keyword match quality (capped at 50)
