592→          summary,
593→          skill_score: null,
594→          experience_score: null,
595→          education_score: null,
596→        };
597→
598→        if (existingResult) {
599→          await supabase.from("results").update(resultData as any).eq("id", existingResult.id);
600→        } else {
601→          await supabase.from("results").insert(resultData as any);
602→        }
603→      }
604→      console.log(`Heuristic scored ${unscoredIds.length} resumes`);
