import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { toast } from "sonner";

export type HiringStage = "applied" | "screened" | "interview" | "offer" | "hired" | "rejected";

export const STAGE_ORDER: HiringStage[] = ["applied", "screened", "interview", "offer", "hired"];

export interface CandidateStage {
  id: string;
  resume_id: string;
  job_id: string;
  stage: HiringStage;
  updated_at: string;
}

export function useStages(jobId: string | null) {
  return useQuery({
    queryKey: ["candidate-stages", jobId],
    queryFn: async () => {
      if (!jobId) return [];
      const { data, error } = await (supabase as any)
        .from("candidate_stages")
        .select("id, resume_id, job_id, stage, updated_at")
        .eq("job_id", jobId);
      if (error) throw error;
      return (data ?? []) as CandidateStage[];
    },
    enabled: !!jobId,
  });
}

export function useUpdateStage() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({
      resumeId,
      jobId,
      newStage,
      currentStage,
    }: {
      resumeId: string;
      jobId: string;
      newStage: HiringStage;
      currentStage?: HiringStage | null;
    }) => {
      // Upsert the current stage
      const { error: upsertError } = await (supabase as any)
        .from("candidate_stages")
        .upsert(
          {
            resume_id: resumeId,
            job_id: jobId,
            stage: newStage,
            updated_at: new Date().toISOString(),
            updated_by: user?.id,
          },
          { onConflict: "resume_id,job_id" }
        );
      if (upsertError) throw upsertError;

      // Log the transition
      const { error: historyError } = await (supabase as any)
        .from("stage_history")
        .insert({
          resume_id: resumeId,
          job_id: jobId,
          from_stage: currentStage || null,
          to_stage: newStage,
          changed_by: user?.id,
        });
      if (historyError) throw historyError;
    },
    onMutate: async (variables) => {
      // Optimistic update: immediately reflect the stage change in UI
      await queryClient.cancelQueries({ queryKey: ["candidate-stages", variables.jobId] });
      const previous = queryClient.getQueryData<CandidateStage[]>(["candidate-stages", variables.jobId]);
      queryClient.setQueryData<CandidateStage[]>(["candidate-stages", variables.jobId], (old) => {
        if (!old) return [{ id: "optimistic", resume_id: variables.resumeId, job_id: variables.jobId, stage: variables.newStage, updated_at: new Date().toISOString() }];
        const exists = old.find((s) => s.resume_id === variables.resumeId);
        if (exists) return old.map((s) => s.resume_id === variables.resumeId ? { ...s, stage: variables.newStage, updated_at: new Date().toISOString() } : s);
        return [...old, { id: "optimistic", resume_id: variables.resumeId, job_id: variables.jobId, stage: variables.newStage, updated_at: new Date().toISOString() }];
      });
      return { previous };
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["candidate-stages", variables.jobId] });
    },
    onError: (error: Error, variables, context) => {
      // Revert optimistic update on error
      if (context?.previous) {
        queryClient.setQueryData(["candidate-stages", variables.jobId], context.previous);
      }
      toast.error(error.message || "Failed to update stage");
    },
  });
}

export function useStageSummary(jobId: string | null) {
  const { data: stages } = useStages(jobId);

  const summary: Record<HiringStage, number> = {
    applied: 0,
    screened: 0,
    interview: 0,
    offer: 0,
    hired: 0,
    rejected: 0,
  };

  if (stages) {
    stages.forEach((s) => {
      if (summary[s.stage] !== undefined) {
        summary[s.stage]++;
      }
    });
  }

  return summary;
}
